import os, signal
pids = []
for pid in os.listdir('/proc'):
    if not pid.isdigit():
        continue
    try:
        with open(f'/proc/{pid}/cmdline','rb') as f:
            cmd = f.read().decode(errors='ignore').replace('\x00',' ')
    except Exception:
        continue
    if 'python' in cmd and 'qutip' in cmd:
        pids.append((int(pid), cmd))
# if not found, try any python running from stdin (looks like '- <<')
if not pids:
    for pid in os.listdir('/proc'):
        if not pid.isdigit():
            continue
        try:
            with open(f'/proc/{pid}/cmdline','rb') as f:
                cmd = f.read().decode(errors='ignore').replace('\x00',' ')
        except Exception:
            continue
        if cmd.startswith('python ') and 'qutip' in cmd:
            pids.append((int(pid), cmd))

for pid, cmd in pids:
    try:
